-- newsletter (WP-50; marketing-surfaces spec, Backend contract): newsletter_subscribers (double opt-in sign-ups, token
-- hashes only, no request metadata) and the newsletter_confirm email kind, which like contact_message has no user_id.
-- Generated by drizzle-kit; the only hand edit is this header. The new table is empty, so its indexes build in the
-- transaction; email_sends' two checks are dropped and re-added validated, a scan of a table that holds at most 120 days
-- of ledger rows. Grants: ops/provision-roles.sql.
CREATE TABLE "newsletter_subscribers" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"email" text NOT NULL,
	"email_hash" text,
	"source" text NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"confirm_seq" integer DEFAULT 1 NOT NULL,
	"confirm_requested_at" timestamp with time zone DEFAULT now() NOT NULL,
	"confirm_token_hash" "bytea",
	"confirm_expires_at" timestamp with time zone,
	"unsubscribe_token_hash" "bytea",
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"confirmed_at" timestamp with time zone,
	"unsubscribed_at" timestamp with time zone,
	CONSTRAINT "newsletter_subscribers_email_ck" CHECK ("newsletter_subscribers"."email" = lower(btrim("newsletter_subscribers"."email")) AND char_length("newsletter_subscribers"."email") BETWEEN 3 AND 254 AND position('@' in "newsletter_subscribers"."email") > 1),
	CONSTRAINT "newsletter_subscribers_email_hash_ck" CHECK ("newsletter_subscribers"."email_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "newsletter_subscribers_source_ck" CHECK ("newsletter_subscribers"."source" IN ('popup','blog-index','blog-post','about')),
	CONSTRAINT "newsletter_subscribers_status_ck" CHECK ("newsletter_subscribers"."status" IN ('pending','confirmed','unsubscribed')),
	CONSTRAINT "newsletter_subscribers_seq_ck" CHECK ("newsletter_subscribers"."confirm_seq" >= 1),
	CONSTRAINT "newsletter_subscribers_hash_ck" CHECK (("newsletter_subscribers"."confirm_token_hash" IS NULL OR octet_length("newsletter_subscribers"."confirm_token_hash") = 32) AND ("newsletter_subscribers"."unsubscribe_token_hash" IS NULL OR octet_length("newsletter_subscribers"."unsubscribe_token_hash") = 32)),
	CONSTRAINT "newsletter_subscribers_confirm_ck" CHECK (("newsletter_subscribers"."confirm_token_hash" IS NULL) = ("newsletter_subscribers"."confirm_expires_at" IS NULL) AND ("newsletter_subscribers"."confirm_token_hash" IS NULL OR "newsletter_subscribers"."status" = 'pending')),
	CONSTRAINT "newsletter_subscribers_state_ck" CHECK (("newsletter_subscribers"."status" <> 'pending' OR ("newsletter_subscribers"."confirmed_at" IS NULL AND "newsletter_subscribers"."unsubscribed_at" IS NULL)) AND ("newsletter_subscribers"."status" <> 'confirmed' OR ("newsletter_subscribers"."confirmed_at" IS NOT NULL AND "newsletter_subscribers"."unsubscribed_at" IS NULL)) AND ("newsletter_subscribers"."status" <> 'unsubscribed' OR "newsletter_subscribers"."unsubscribed_at" IS NOT NULL))
);
