CREATE UNIQUE INDEX "newsletter_subscribers_unsubscribe_uq" ON "newsletter_subscribers" USING btree ("unsubscribe_token_hash") WHERE "newsletter_subscribers"."unsubscribe_token_hash" IS NOT NULL;--> statement-breakpoint
CREATE INDEX "newsletter_subscribers_email_hash_idx" ON "newsletter_subscribers" USING btree ("email_hash") WHERE "newsletter_subscribers"."email_hash" IS NOT NULL;--> statement-breakpoint
CREATE INDEX "newsletter_subscribers_inactive_idx" ON "newsletter_subscribers" USING btree ("status","confirm_requested_at") WHERE "newsletter_subscribers"."status" <> 'confirmed';--> statement-breakpoint
ALTER TABLE "email_sends" ADD CONSTRAINT "email_sends_kind_ck" CHECK ("email_sends"."kind" IN ('digest','autopilot_hourly','autopilot_paused','resend_available','offer_pause_notice','offer_pause_applied','forwarding_code','outcome_report','return_to_draft','contact_message','newsletter_confirm'));--> statement-breakpoint
